    else if (e.key === "2") setDepth("2");
    else if (e.key === "0") setDepth("a");
  });

  /* ---------- 启动（同步，无加载态） ---------- */
  layout();
  buildGraph();
  renderLegend();
  var init = parseHash();
  if (!init.home && !init.trail.length && !init.error) init.trail = [CORE]; /* task-first：默认聚焦枢纽 */
  apply(init);
  if (state.kb) setTimeout(function () { sInput.focus(); }, 60);
})();

